#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

struct Point {
    long long u, v;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<long long> x(n), y(n);
    for (int i = 0; i < n; ++i) {
        cin >> x[i];
    }
    for (int i = 0; i < n; ++i) {
        cin >> y[i];
    }

    if (n <= 2) {
        cout << 0 << "\n";
        return 0;
    }

    vector<Point> pts(n);
    long long min_u = 4e18, max_u = -4e18;
    long long min_v = 4e18, max_v = -4e18;

    for (int i = 0; i < n; ++i) {
        pts[i].u = x[i] + y[i];
        pts[i].v = x[i] - y[i];
        min_u = min(min_u, pts[i].u);
        max_u = max(max_u, pts[i].u);
        min_v = min(min_v, pts[i].v);
        max_v = max(max_v, pts[i].v);
    }

    auto check = [&](long long D) -> bool {
        if (max_u - min_u > 2 * D || max_v - min_v > 2 * D) {
            return false;
        }

        // Configuração 1:
        // Q1: u <= min_u + D e v <= min_v + D
        // Q2: u >= max_u - D e v >= max_v - D
        bool ok1 = true;
        for (int i = 0; i < n; ++i) {
            bool in_q1 = (pts[i].u <= min_u + D && pts[i].v <= min_v + D);
            bool in_q2 = (pts[i].u >= max_u - D && pts[i].v >= max_v - D);
            if (!in_q1 && !in_q2) {
                ok1 = false;
                break;
            }
        }
        if (ok1) return true;

        // Configuração 2:
        // Q1: u <= min_u + D e v >= max_v - D
        // Q2: u >= max_u - D e v <= min_v + D
        bool ok2 = true;
        for (int i = 0; i < n; ++i) {
            bool in_q1 = (pts[i].u <= min_u + D && pts[i].v >= max_v - D);
            bool in_q2 = (pts[i].u >= max_u - D && pts[i].v <= min_v + D);
            if (!in_q1 && !in_q2) {
                ok2 = false;
                break;
            }
        }
        return ok2;
    };

    long long low = 0, high = 1000000000LL, ans = high;
    while (low <= high) {
        long long mid = low + (high - low) / 2;
        if (check(mid)) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }

    cout << ans << "\n";

    return 0;
}
